//! Stable MCL identifier generation (`SPEC-004 §5.1`).
//!
//! IDs are:
//! - globally unique within a project,
//! - immutable after creation,
//! - never derived solely from a display name,
//! - generated by the core (here), never trusted from model output.
//!
//! The form is `<prefix>-<ULID>`, matching the spec examples (`concept-01JY...`). ULIDs are
//! lexicographically sortable by creation time, which is convenient for history and debugging.

use ulid::Ulid;

/// Generate a new stable ID with the given kind prefix, e.g. `new_id("concept")`.
///
/// The prefix should be a short lowercase kind such as `concept`, `recipe`, `behavior`,
/// `appearance`. Transaction IDs use a separate monotonic scheme (see the state manager) and do
/// not go through this function.
pub fn new_id(prefix: &str) -> String {
    format!("{prefix}-{}", Ulid::new())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_prefixed_and_unique() {
        let a = new_id("concept");
        let b = new_id("concept");
        assert!(a.starts_with("concept-"));
        assert!(b.starts_with("concept-"));
        assert_ne!(a, b, "generated IDs must be unique");
    }

    #[test]
    fn many_ids_are_unique() {
        let mut set = std::collections::HashSet::new();
        for _ in 0..1000 {
            assert!(set.insert(new_id("recipe")), "collision in generated IDs");
        }
    }
}
